<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $completion = sd_profile_completion(); ?><section class="sd-dashboard-card sd-profile-completion"><div class="sd-card-heading"><div><span class="sd-eyebrow"><?php esc_html_e( 'Profile health', 'social-discovery' ); ?></span><h2><?php esc_html_e( 'Complete your profile', 'social-discovery' ); ?></h2></div><strong><?php echo esc_html( $completion['percent'] ); ?>%</strong></div><div class="sd-progress" role="progressbar" aria-valuenow="<?php echo esc_attr( $completion['percent'] ); ?>" aria-valuemin="0" aria-valuemax="100"><span style="width:<?php echo esc_attr( $completion['percent'] ); ?>%"></span></div><?php if ( ! empty( $completion['missing'] ) ) : ?><ul><?php foreach ( $completion['missing'] as $key => $label ) : ?><li><a href="<?php echo esc_url( 'privacy' === $key ? sd_auth_account_url() : sd_auth_profile_url() ); ?>"><?php echo esc_html( $label ); ?></a></li><?php endforeach; ?></ul><?php else : ?><p class="sd-muted"><?php esc_html_e( 'Your public profile is ready for discovery.', 'social-discovery' ); ?></p><?php endif; ?></section>
